-- Learn guides rewritten as short, sourced steps. Temperatures follow USDA FSIS;
-- method follows The Culinary Institute of America's The Professional Chef and
-- Harold McGee's On Food and Cooking. Additive: updates seeded rows in place.
UPDATE techniques SET minutes=10, summary='Boil briefly, then chill in iced water to set colour and stop the cooking.', body='1. Bring a large pot of well-salted water to a rolling boil and set a bowl of iced water beside it.' || char(10) || '2. Add the vegetables in small batches so the water keeps boiling; cook 30 seconds to 3 minutes until bright and just tender.' || char(10) || '3. Lift straight into the iced water, then drain and pat dry.' || char(10) || '**Why it works:** brief heat sets the green pigment before enzymes dull it; the ice bath stops carry-over cooking. Also loosens tomato and peach skins.' || char(10) || 'Sources: The Culinary Institute of America, The Professional Chef; Harold McGee, On Food and Cooking.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE slug='blanching';
UPDATE techniques SET minutes=15, summary='Brown the surface hard in a hot, dry-ish pan for deep flavour, then finish gently.', body='1. Pat the food completely dry and season with salt; a wet surface steams instead of browning.' || char(10) || '2. Heat a heavy pan over medium-high until a thin film of high-smoke-point oil shimmers.' || char(10) || '3. Lay the food in away from you and **leave it alone** for 2–4 minutes; it releases once a crust forms. Turn once.' || char(10) || '4. Finish to a safe internal temperature: whole beef, pork or lamb 63°C / 145°F with a 3-minute rest; ground meat 71°C / 160°F; poultry 74°C / 165°F.' || char(10) || '**Why it works:** above about 140°C the Maillard reaction builds hundreds of savoury compounds; the browned bits (fond) become a pan sauce.' || char(10) || 'Sources: USDA FSIS Safe Minimum Internal Temperature Chart https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/safe-temperature-chart; Harold McGee, On Food and Cooking.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE slug='searing';
UPDATE techniques SET minutes=10, summary='Even matchsticks, about 3 mm square, for fast and uniform cooking.', body='1. Trim one side flat so the vegetable sits still, then cut 5–6 cm lengths.' || char(10) || '2. Slice into planks about 3 mm thick.' || char(10) || '3. Stack two or three planks and slice again into 3 mm sticks.' || char(10) || '4. Curl the fingertips of your guiding hand (the claw) and keep the blade tip on the board. Evenness beats speed.' || char(10) || 'Sources: The Culinary Institute of America, The Professional Chef.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE slug='julienne';
UPDATE techniques SET minutes=12, summary='Cook over, not in, simmering water: gentle, fat-free heat that keeps colour and texture.', body='1. Bring 2–3 cm of water to a simmer in a pot with a steamer basket or rack above the water line.' || char(10) || '2. Add food in a single layer, cover, and keep the water at a steady simmer.' || char(10) || '3. Check early: leafy greens 2–4 minutes, broccoli florets 5–7, sliced carrots 8–10, fish fillets 6–10.' || char(10) || '4. Season after cooking; steam adds no salt of its own.' || char(10) || '**Why it works:** steam transfers heat at 100°C without leaching water-soluble vitamins into the pot.' || char(10) || 'Sources: The Culinary Institute of America, The Professional Chef; Harold McGee, On Food and Cooking.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE slug='steaming';
UPDATE techniques SET minutes=45, summary='Low heat and patience turn sliced onions deep gold and sweet.', body='1. Slice 3–4 onions thinly and add to a wide pan with a spoonful of oil or butter over medium-low heat, with a pinch of salt.' || char(10) || '2. Stir every few minutes. Expect 35–45 minutes; anything under 15 is softened, not caramelised.' || char(10) || '3. When the fond darkens, add a splash of water and scrape it back into the onions. Repeat as needed.' || char(10) || '4. Stop at deep amber, before any black edges. No added sugar is needed.' || char(10) || '**Why it works:** slow heat breaks the onion''s sugars down and browns them without scorching.' || char(10) || 'Sources: Harold McGee, On Food and Cooking; Serious Eats, How to Caramelize Onions.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE slug='caramelizing-onions';
UPDATE techniques SET minutes=40, summary='Dry oven heat browns the outside while the inside cooks through.', body='1. Heat the oven to 200–220°C / 400–425°F.' || char(10) || '2. Toss vegetables or meat with oil and salt and spread them in a single layer with space between pieces; crowding steams.' || char(10) || '3. Roast 25–40 minutes for hard vegetables, turning once halfway for even colour.' || char(10) || '4. Check meat with a thermometer: poultry 74°C / 165°F; whole cuts of beef, pork or lamb 63°C / 145°F plus a 3-minute rest.' || char(10) || 'Sources: USDA FSIS Safe Minimum Internal Temperature Chart https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/safe-temperature-chart; The Culinary Institute of America, The Professional Chef.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE slug='roasting';
UPDATE techniques SET minutes=10, summary='Quick cooking in a little hot fat, with small pieces kept moving.', body='1. Cut everything to a similar small size so it cooks in the same time.' || char(10) || '2. Heat the pan first, then add just enough oil to film it. It should shimmer.' || char(10) || '3. Add food in one layer without crowding; cook in batches if needed.' || char(10) || '4. Keep the pieces moving with a toss or a spatula, 3–8 minutes, then finish with acid, herbs or a splash of stock.' || char(10) || 'Sources: The Culinary Institute of America, The Professional Chef.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE slug='sauteing';
UPDATE techniques SET minutes=150, summary='Brown, then cook slowly in a little liquid until tough cuts turn tender.', body='1. Season and brown the meat or vegetables on all sides; remove.' || char(10) || '2. Soften onion, carrot and celery in the same pot, add tomato paste or spices, then liquid (stock, wine, water) to come a third to halfway up the food.' || char(10) || '3. Return the food, cover, and keep at a bare simmer: a 150–160°C / 300–325°F oven is easiest.' || char(10) || '4. Cook 1.5–3 hours until fork-tender; let it rest in the liquid, then skim fat and season.' || char(10) || '**Why it works:** long, moist heat converts collagen in tough cuts into gelatin, which makes the sauce silky.' || char(10) || 'Sources: Harold McGee, On Food and Cooking; The Culinary Institute of America, The Professional Chef.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE slug='braising';
UPDATE techniques SET minutes=5, summary='Turn the browned bits left after searing into a sauce in two minutes.', body='1. After searing, pour off all but a spoonful of fat and return the pan to medium heat.' || char(10) || '2. Add 60–120 ml of liquid (wine, stock, cider or water) and scrape the browned bits loose with a wooden spoon.' || char(10) || '3. Simmer until reduced by about half, then swirl in a knob of cold butter off the heat and season.' || char(10) || 'Sources: The Culinary Institute of America, The Professional Chef; Harold McGee, On Food and Cooking.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE slug='deglazing';
UPDATE techniques SET minutes=10, summary='Read, measure and chop before the heat goes on, so cooking is calm.', body='1. Read the recipe to the end and note timings and oven temperature.' || char(10) || '2. Measure and chop every ingredient; group them by the step that uses them.' || char(10) || '3. Get the pans, tools and serving dishes out, and put a bowl for scraps on the counter.' || char(10) || '4. Clean as you go: a clear board and sink keep the last steps as easy as the first.' || char(10) || 'Sources: The Culinary Institute of America, The Professional Chef.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE slug='mise-en-place';
UPDATE techniques SET minutes=10, summary='A short rest after cooking keeps juices in the meat instead of on the board.', body='1. Move cooked meat to a warm plate or board; tent loosely with foil if resting more than 10 minutes.' || char(10) || '2. Rest steaks and chops 5–10 minutes, roasts 15–30 minutes. The internal temperature keeps rising 3–8°C, so pull meat a little early.' || char(10) || '3. Slice against the grain and add any board juices back to the plate or sauce.' || char(10) || '**Note:** USDA treats a 3-minute rest as part of the safe minimum for whole cuts cooked to 63°C / 145°F.' || char(10) || 'Sources: USDA FSIS Safe Minimum Internal Temperature Chart https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/safe-temperature-chart; Harold McGee, On Food and Cooking.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE slug='resting-meat';
UPDATE techniques SET minutes=5, summary='A dry pan or a little hot oil wakes up whole and ground spices.', body='1. Whole spices: heat a dry pan over medium, add the spices and shake for 1–3 minutes until fragrant and a shade darker. Tip out at once and grind after cooling.' || char(10) || '2. Ground spices: bloom them in the hot oil for 30–60 seconds at the start of a dish, before wet ingredients go in.' || char(10) || '3. Both burn fast; if you smell scorching, start again.' || char(10) || '**Why it works:** heat releases and rearranges the spices'' aromatic oils, and fat carries them through the dish.' || char(10) || 'Sources: Harold McGee, On Food and Cooking.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE slug='toasting-spices';
UPDATE techniques SET minutes=15, summary='Butter and flour cooked together thicken sauces, soups and stews.', body='1. Melt equal weights of butter and flour (about 1 tablespoon each thickens 240 ml of liquid to a light sauce) over medium heat and whisk smooth.' || char(10) || '2. Cook to the colour you need: 2 minutes for a white roux, 5–10 for blond, 20–45 for the dark, nutty roux behind a gumbo. Darker roux thickens less.' || char(10) || '3. Add liquid gradually while whisking, then simmer at least 5 minutes so the floury taste cooks out.' || char(10) || 'Sources: The Culinary Institute of America, The Professional Chef; Harold McGee, On Food and Cooking.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE slug='making-a-roux';
UPDATE techniques SET minutes=15, summary='Cook gently in liquid held well below the boil, for tender eggs, chicken and fish.', body='1. Bring the liquid to 70–85°C / 160–185°F: small bubbles on the pan base, no rolling boil.' || char(10) || '2. Eggs: crack fresh eggs into a cup, slide into the water with a splash of vinegar, and cook 3–4 minutes for a runny yolk.' || char(10) || '3. Chicken breast: cover with stock, keep at that temperature 12–15 minutes, and check for 74°C / 165°F inside. Fish fillets need 8–10 minutes.' || char(10) || '**Why it works:** proteins set gently at these temperatures and stay moist instead of tightening.' || char(10) || 'Sources: USDA FSIS Safe Minimum Internal Temperature Chart https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/safe-temperature-chart; Harold McGee, On Food and Cooking.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE slug='poaching';
UPDATE techniques SET minutes=25, summary='Two heat zones, a clean oiled grate and a thermometer make grilling predictable.', body='1. Preheat 10–15 minutes with the lid down, then scrape the grate and wipe it with an oiled cloth.' || char(10) || '2. Set two zones: direct heat for searing, a cooler side for finishing thick pieces without burning.' || char(10) || '3. Oil the food lightly, lay it on the hot side and turn once when it releases; move it to the cool side to finish.' || char(10) || '4. Check inside: poultry 74°C / 165°F, ground meat 71°C / 160°F, whole cuts 63°C / 145°F plus a 3-minute rest. Rest before slicing.' || char(10) || 'Sources: USDA FSIS Safe Minimum Internal Temperature Chart https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/safe-temperature-chart; The Culinary Institute of America, The Professional Chef.', updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE slug='grilling';
